// 三数之和的变种
int main() {
    string s;
    cin >> s;
    vector<string> ansString = split(s, ",");
    int n = ansString.size();
    vector<int> ans(n);
    for (int i = 0; i < n; i++) {
        ans[i] = stoi(ansString[i]);
    }
    int totalMoney;
    cin >> totalMoney;
    // 排序
    sort(ans.begin(),  ans.end());
​
    int res = -1;
    int diff = INT_MAX; 
    for (int i = 0; i < n -2; i++) {
        int left = i + 1, right  = n -1;
        while (left < right) {
            int tmp = ans[i] + ans[left] + ans[right];
            if (tmp > totalMoney) {
                right--;
            } else {
                if (diff > totalMoney - tmp)  {
                    res = tmp;
                    diff = totalMoney - tmp;
                }
                break;
            }
        }
    }
    cout << res;
    return 0;
}

