public class Main {
    // 通用 split 方法
    public static List<Integer> splitAndConvert(String str, String delimiter) {
        List<Integer> result = new ArrayList<>();
        String[] parts = str.split(delimiter);
        for (String part : parts) {
            result.add(Integer.parseInt(part));
        }
        return result;
    }
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.next();
        List<Integer> ans = splitAndConvert(s, ",");
        int totalMoney = scanner.nextInt();
        scanner.close();

        // 排序
        Collections.sort(ans);
        int res = -1;
        int diff = Integer.MAX_VALUE;
        int n = ans.size();

        for (int i = 0; i < n - 2; i++) {
            int left = i + 1, right = n - 1;
            while (left < right) {
                int tmp = ans.get(i) + ans.get(left) + ans.get(right);
                if (tmp > totalMoney) {
                    right--;
                } else {
                    if (diff > totalMoney - tmp) {
                        res = tmp;
                        diff = totalMoney - tmp;
                    }
                    break;
                }
            }
        }
        System.out.println(res);
    }
}
