import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
​
​
func main() {
    // 读取输入
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    input := scanner.Text()
    ansString := strings.Split(input, ",")
​
    n := len(ansString)
    ans := make([]int, n)
    for i := 0; i < n; i++ {
        num, _ := strconv.Atoi(ansString[i])
        ans[i] = num
    }
​
    scanner.Scan()
    totalMoney, _ := strconv.Atoi(scanner.Text())
​
    // 排序
    sort.Ints(ans)
​
    res := -1
    diff := int(^uint(0) >> 1) // 最大值
​
    for i := 0; i < n-2; i++ {
        left, right := i+1, n-1
        for left < right {
            tmp := ans[i] + ans[left] + ans[right]
            if tmp > totalMoney {
                right--
            } else {
                if diff > totalMoney-tmp {
                    res = tmp
                    diff = totalMoney - tmp
                }
                break
            }
        }
    }
​
    fmt.Println(res)
}
